db.customers.createIndex({ city: 1, loyalty_tier: 1 });
db.restaurants.createIndex({ city: 1 });
db.menu_items.createIndex({ restaurant_id: 1, price: 1 });
db.orders.createIndex({ customer_id: 1 });
db.orders.createIndex({ restaurant_id: 1, order_date: -1 });
db.orders.createIndex({ status: 1, order_date: -1 });
db.reviews.createIndex({ restaurant_id: 1 });

print("Seed complete:");
["customers", "restaurants", "menu_items", "delivery_agents", "orders", "reviews"].forEach(function (c) {
  print("  " + c + ": " + db.getCollection(c).countDocuments());
});
